card_mod.style:
{% set t = states('sensor.outdoor_weather_station_outdoor_temperature') | float(999) %} {% set h = states('sensor.outdoor_weather_station_humidity') | float(999) %}
{% set ideal = (t > 18 and t < 23 and h > 40 and h < 62) %} {% set usable = (t < 25 and h < 70 and not ideal) %}
ha-card {
  position: relative;
  border-radius: 18px !important;
  overflow: hidden;

  {% if ideal %}
    background: rgba(0, 255, 120, 0.14);
  {% elif usable %}
    background: rgba(255, 220, 0, 0.10);
    animation: pulseYellow 1.2s ease-in-out infinite;
  {% else %}
    background: rgba(255, 60, 60, 0.12);
  {% endif %}
}
/* ── Cause icons row ───────────────────────────── */ ha-card::after {
  content: "
  {% if ideal %}✔{% endif %}
  {% if t <= 18 %}❄{% endif %}
  {% if t >= 25 %}🔥{% endif %}
  {% if h >= 70 %}💧{% endif %}
  ";
  position: absolute;
  bottom: 8px;
  right: 12px;
  font-size: 1.1em;
  letter-spacing: 4px;
  opacity: 0.9;
}
{% if usable %} @keyframes pulseYellow {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.02); }
  100% { transform: scale(1); }
} {% endif %}

{% set t = states('sensor.outdoor_weather_station_outdoor_temperature') | float(999) %} {% set h = states('sensor.outdoor_weather_station_humidity') | float(999) %}
{% set green = (t > 18 and t < 23 and h > 40 and h < 62) %} {% set yellow = (t < 25 and h < 70 and not green) %} {% set red = not (green or yellow) %}
{% if green %}
  {% set reason = "Outdoor air ideal" %}
{% elif yellow %}
  {% if t >= 23 %}
    {% set reason = "Acceptable – slightly warm" %}
  {% elif h >= 62 %}
    {% set reason = "Acceptable – humidity high" %}
  {% else %}
    {% set reason = "Acceptable – marginal" %}
  {% endif %}
{% else %}
  {% if t <= 18 %}
    {% set reason = "Too cold outside" %}
  {% elif t >= 25 %}
    {% set reason = "Too hot outside" %}
  {% elif h >= 70 %}
    {% set reason = "Humidity too high" %}
  {% else %}
    {% set reason = "Conditions unsuitable" %}
  {% endif %}
{% endif %}
ha-card {
  border-radius: 18px !important;
  overflow: hidden;

  {% if green %}
    background: rgba(0, 255, 120, 0.14);
    box-shadow: inset 0 0 0 1px rgba(0, 255, 120, 0.45);
    animation: none;
  {% elif yellow %}
    background: rgba(255, 220, 0, 0.10);
    box-shadow: inset 0 0 0 1px rgba(255, 220, 0, 0.55);
    animation: pulseYellow 1.2s ease-in-out infinite;
  {% else %}
    background: rgba(255, 60, 60, 0.12);
    box-shadow: inset 0 0 0 1px rgba(255, 60, 60, 0.55);
    animation: none;
  {% endif %}
}
/* 🔁 Replace state content */ ha-card .state::after {
  content: "{{ reason }}";
  font-size: 0.8em;
  font-weight: 500;
  opacity: 0.9;
}
{% if yellow %} @keyframes pulseYellow {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.02); }
  100% { transform: scale(1); }
} {% endif %}

card.background-image:
[[[
  const img = variables.image;
  const pot = variables.pot;
  const privEnt = `input_boolean.pot_${pot}_private_view`;
  const privateOn = states[privEnt]?.state === 'on';

  if (privateOn) {
    // Privacy mode: no plant image, just a neutral/digital background
    return `
      radial-gradient(circle at top left, rgba(0,200,150,0.12), transparent 55%),
      radial-gradient(circle at bottom right, rgba(0,150,255,0.16), transparent 55%),
      linear-gradient(to top, rgba(0,0,0,0.95) 0%, rgba(10,10,10,0.9) 40%, rgba(0,0,0,0.85) 100%) !important
    `;
  }

  // Normal mode: gradient + plant image
  return `
    linear-gradient(
      to top,
      rgba(0,0,0,0.9) 0%,
      rgba(0,0,0,0.25) 40%,
      rgba(0,0,0,0.0) 70%
    ),
    url("/local/${img}") !important
  `;
]]]

card_mod.style:
@keyframes dripPulse {
  0%   { box-shadow: 0 0 10px rgba(0, 191, 255, 0.3); }
  50%  { box-shadow: 0 0 26px rgba(0, 191, 255, 1); }
  100% { box-shadow: 0 0 10px rgba(0, 191, 255, 0.3); }
}
@keyframes vpdPulse {
  0%   { box-shadow: 0 0 10px rgba(255, 80, 80, 0.4); }
  50%  { box-shadow: 0 0 28px rgba(255, 80, 80, 1); }
  100% { box-shadow: 0 0 10px rgba(255, 80, 80, 0.4); }
}

custom_fields.bar:
[[[
  const pot = variables.pot;

  const fmt = (id, def, dec) => {
    const obj = states[id];
    if (!obj || obj.state === 'unknown' || obj.state === 'unavailable') return def;
    const n = parseFloat(obj.state);
    if (isNaN(n)) return def;
    return dec === 0 ? Math.round(n) : n.toFixed(dec);
  };

  const moist = fmt(`sensor.dsc_pot${pot}_soil_moisture`, '–', 0);
  const ec    = fmt(`sensor.dsc_pot${pot}_soil_conductivity`, '–', 0);
  const ph    = fmt(`sensor.dsc_pot${pot}_soil_ph`, '–', 1);
  const temp  = fmt(`sensor.dsc_pot${pot}_soil_temperature`, '–', 1);
  const n     = fmt(`sensor.dsc_pot${pot}_soil_nitrogen`, '–', 0);
  const p     = fmt(`sensor.dsc_pot${pot}_soil_phosphorus`, '–', 0);
  const k     = fmt(`sensor.dsc_pot${pot}_soil_potassium`, '–', 0);

  let soilStatus = 'OK';
  const mNum = parseFloat(moist);
  const tNum = parseFloat(temp);

  if (!isNaN(mNum)) {
    if (mNum < 40) soilStatus = 'Dry';
    else if (mNum > 65) soilStatus = 'Wet';
  }
  if (!isNaN(tNum)) {
    if (tNum < 18) soilStatus = 'Cool';
    else if (tNum > 26) soilStatus = 'Warm';
  }

  return `
    <div style="
      display:flex;
      justify-content:space-between;
      align-items:center;
      width:100%;
      white-space:nowrap;
    ">
      <div style="display:flex; gap:12px; align-items:center; white-space:nowrap;">
        <span style="color:#4dabf7;">💧 ${moist}%</span>
        <span style="color:#9b59b6;">⚡ ${ec} µS/cm</span>
        <span style="color:#2ecc71;">🧪 ${ph} pH</span>
        <span style="color:#ffb347;">🌡 ${temp} °C</span>
        <span style="color:#f1c40f;">N ${n}</span>
        <span style="color:#e67e22;">P ${p}</span>
        <span style="color:#00cec9;">K ${k}</span>
      </div>

      <div style="
        padding-left:14px;
        padding-right:12px;
        font-size:10px;
        opacity:0.85;
        text-align:right;
        white-space:nowrap;
      ">
        · Soil: ${soilStatus}
      </div>
    </div>
  `;
]]]

